on conflict (id) do update set title=excluded.title,author=excluded.author,category=excluded.category,rating=excluded.rating,year=excluded.year,pages=excluded.pages,language=excluded.language,description=excluded.description,download_url=excluded.download_url,image_url=excluded.image_url,file_size=excluded.file_size,format=excluded.format,download_count=excluded.download_count,comments=excluded.comments,added_date=excluded.added_date;
select setval(pg_get_serial_sequence('public.books','id'), coalesce((select max(id) from public.books), 1), exists(select 1 from public.books));
do $$ begin
  if not exists (select 1 from pg_constraint where conrelid = 'public.user_library'::regclass and conname = 'user_library_book_id_fkey') then
    alter table public.user_library add constraint user_library_book_id_fkey foreign key (book_id) references public.books(id) on delete cascade;
  end if;
end $$;
commit;
